message.content:
{
  "description": "The creature is shown in right-facing side profile against a plain off-white background, with a stocky, bear-like body covered in dense, shaggy brown fur that is darker on the lower legs and lighter tan on the muzzle, cheeks and lower flanks. Its back from the shoulders to the hindquarters is covered by a large, domed, glossy dark reddish-brown shell resembling a beetle's elytra, divided into two main sections, and a single long, dark, curved horn projects upward and backward from its forehead. It stands on four thick, clawed legs with a small furry tail at the rear, giving the overall appearance of a bear-beetle hybrid.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, broad with a tapered muzzle, covered in brown fur with a lighter tan muzzle and lower cheek, black nose at the tip, small dark brown eyes, and a closed mouth",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single thick, glossy, dark brown to black horn, smooth with a ridged base where it meets the fur, curving backward and upward to a sharp pointed tip",
      "where": "on the midline of the forehead, between and just in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears covered in dense brown fur",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, columnar legs covered in long shaggy brown fur, darker brown toward the bottom",
      "where": "under the body, two forelegs under the chest/shoulder and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with visible pale curved claws on the toes, the fur covering the top of the paws",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, stubby tail covered in brown fur",
      "where": "at the rear of the body, protruding from the hindquarters just below the back edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "large, domed, hard-looking, glossy dark reddish-brown carapace with fine horizontal ridges and light reflections, divided into a smaller anterior section over the shoulders and a larger posterior section over the back and hindquarters, with a narrow lighter joint between them",
      "where": "covering the entire dorsal side of the torso from just behind the neck to above the tail"
    },
    {
      "part": "plates",
      "looks_like": "a border of small, rectangular, brown plates each with a shallow oval depression, forming a segmented rim",
      "where": "along the lower perimeter edge of both sections of the shell, encircling the shell where it meets the fur"
    },
    {
      "part": "markings",
      "looks_like": "patches of lighter cream-tan fur contrasting with the darker brown fur",
      "where": "on the lower sides of the torso, chest area, and around the muzzle"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
